                <span>🔍</span> SARIMA Hyperparameter Search: (p, d, q)(P, D, Q)s Result Table ({activeProfile.label})
              </h4>
              <p style={{ margin: '5px 0 0 0', color: '#556b5b', fontSize: '0.88rem' }}>
                Evaluates parameter combinations across Seasonal and Non-Seasonal loops for <strong>{activeProfile.label} ({activeProfile.unit})</strong> to find the combination with <strong>Minimum AIC</strong>.
              </p>
            </div>

            <div style={{ overflowX: 'auto', borderRadius: '10px', border: '1px solid #d5e5d5' }}>
              <table style={{ width: '100%', borderCollapse: 'collapse', textAlign: 'left', fontSize: '0.92rem' }}>
                <thead>
                  <tr style={{ background: '#243734', color: '#ffffff' }}>
                    <th style={{ background: '#243734', color: '#ffffff', padding: '14px 16px', fontWeight: '700', fontSize: '0.85rem', letterSpacing: '0.3px', textAlign: 'left', border: 'none' }}>
                      Candidate Parameter Combination
                    </th>
                    <th style={{ background: '#243734', color: '#ffffff', padding: '14px 16px', fontWeight: '700', fontSize: '0.85rem', letterSpacing: '0.3px', textAlign: 'center', border: 'none' }}>
                      CV Metric (AIC)
                    </th>
                    <th style={{ background: '#243734', color: '#ffffff', padding: '14px 16px', fontWeight: '700', fontSize: '0.85rem', letterSpacing: '0.3px', textAlign: 'center', border: 'none' }}>
                      RMSE ({activeProfile.unit})
                    </th>
                    <th style={{ background: '#243734', color: '#ffffff', padding: '14px 16px', fontWeight: '700', fontSize: '0.85rem', letterSpacing: '0.3px', textAlign: 'center', border: 'none' }}>
                      MAE ({activeProfile.unit})
                    </th>
                    <th style={{ background: '#243734', color: '#ffffff', padding: '14px 16px', fontWeight: '700', fontSize: '0.85rem', letterSpacing: '0.3px', textAlign: 'center', border: 'none' }}>
                      MAPE
                    </th>
                    <th style={{ background: '#243734', color: '#ffffff', padding: '14px 16px', fontWeight: '700', fontSize: '0.85rem', letterSpacing: '0.3px', textAlign: 'right', border: 'none' }}>
                      Optimization Status
                    </th>
                  </tr>
                </thead>
                <tbody>
                  {(currentTargetResults.sarima?.searchResults || currentTargetResults.sarima?.searchTable || activeProfile.sarimaCandidates).map((c, idx) => (
                    <tr 
                      key={idx} 
                      style={{ 
                        borderBottom: idx === (activeProfile.sarimaCandidates.length - 1) ? 'none' : '1px solid #edf2ed', 
                        background: idx % 2 === 0 ? '#ffffff' : '#fafcfa' 
                      }}
                    >
                      <td style={{ padding: '15px 16px', fontWeight: (c.isBest || idx === 0) ? 'bold' : 'normal', color: '#1f2d24' }}>
                        {c.params || c.shortLabel || c.label}
                      </td>
                      <td style={{ padding: '15px 16px', fontWeight: (c.isBest || idx === 0) ? 'bold' : 'normal', color: (c.isBest || idx === 0) ? '#1f6b3b' : '#333', textAlign: 'center' }}>
                        AIC = {typeof c.aic === 'number' ? c.aic.toFixed(1) : c.aic}
                      </td>
                      <td style={{ padding: '15px 16px', textAlign: 'center', color: '#222' }}>
                        ({typeof c.rmse === 'number' ? c.rmse.toFixed(2) : c.rmse})
                      </td>
                      <td style={{ padding: '15px 16px', textAlign: 'center', color: '#222' }}>
                        ({typeof c.mae === 'number' ? c.mae.toFixed(2) : c.mae})
                      </td>
                      <td style={{ padding: '15px 16px', textAlign: 'center', color: '#222' }}>
                        ({typeof c.mape === 'string' ? c.mape : `${c.mape}%`})
                      </td>
                      <td style={{ padding: '15px 16px', textAlign: 'right' }}>
                        {c.isBest || idx === 0 ? (
                          <span style={{
                            background: '#27ae60',
                            color: '#ffffff',
                            padding: '5px 14px',
                            borderRadius: '14px',
                            fontSize: '0.78rem',
                            fontWeight: 'bold',
                            display: 'inline-block',
                            boxShadow: '0 2px 6px rgba(39, 174, 96, 0.25)'
                          }}>
                            ★ Minimum AIC (Config 1)
                          </span>
                        ) : c.isRunnerUp || idx === 1 ? (
                          <span style={{
                            background: '#e9ebd3',
                            color: '#3e4e20',
                            padding: '5px 14px',
                            borderRadius: '14px',
                            fontSize: '0.78rem',
                            fontWeight: '600',
                            display: 'inline-block'
                          }}>
                            Config 2 (Runner-Up)
                          </span>
                        ) : (
                          <span style={{ color: '#888', fontSize: '0.82rem' }}>
                            Evaluated
                          </span>
                        )}
                      </td>
                    </tr>
                  ))}
                </tbody>
              </table>
            </div>
          </div>

          {/* =================================================================== */}
          {/* 📋 CARD 2: Model Registry Benchmark Table                           */}
          {/* =================================================================== */}
          <div style={{
            background: '#ffffff',
            borderRadius: '16px',
            padding: '24px',
            border: '1px solid #dbe6db',
            boxShadow: '0 4px 18px rgba(0,0,0,0.03)',
            marginBottom: '26px'
          }}>
            <div style={{ display: 'flex', justifyContent: 'space-between', alignItems: 'center', flexWrap: 'wrap', gap: '12px', marginBottom: '16px' }}>
